import test from 'node:test';import assert from 'node:assert/strict';
import {terrainPixel,terrainNoise,terrainTrails,terrainKind,TERRAIN_MATERIALS} from '../terrain-materials.js';
test('terrain is stable, fine grain is bounded and all biomes have distinct material identities',()=>{const colors=new Set();for(const kind of Object.keys(TERRAIN_MATERIALS)){const p=terrainPixel(kind,21,45);assert.deepEqual(p,terrainPixel(kind,21,45));assert.ok(p.every(v=>Number.isInteger(v)&&v>=0&&v<=255));colors.add(p.join(','));}assert.equal(colors.size,Object.keys(TERRAIN_MATERIALS).length);assert.equal(terrainKind('village'),'grass');assert.equal(terrainKind('woodland'),'woodland');for(let x=-10;x<10;x++)assert.ok(terrainNoise(x,7)>=0&&terrainNoise(x,7)<=1);});
test('desire lines follow walkable floor around walls and do not modify a map',()=>{const s={width:7,height:5,floor:['#######','#..#..#','#..#..#','#.....#','#######'],doors:[{xy:[1,1]},{xy:[5,1]}],objects:[]},before=JSON.stringify(s),paths=terrainTrails(s);assert.equal(paths.length,1);assert.deepEqual(paths[0][0],[1,1]);assert.deepEqual(paths[0].at(-1),[5,1]);assert.ok(paths[0].some(p=>p[1]===3));for(const p of paths[0])assert.equal(s.floor[p[1]][p[0]],'.');assert.equal(JSON.stringify(s),before);});
test('desire lines never fabricate bridges over disconnected floor or accept blocked anchors',()=>{const s={width:7,height:3,floor:['#######','#..#..#','#######'],doors:[{xy:[1,1]},{xy:[5,1]},{xy:[3,1]}],objects:[]};assert.deepEqual(terrainTrails(s),[]);});

test('material repeats seamlessly at its cached pattern boundary',()=>{for(const kind of Object.keys(TERRAIN_MATERIALS))for(let y=0;y<384;y+=17){assert.deepEqual(terrainPixel(kind,0,y),terrainPixel(kind,384,y));assert.deepEqual(terrainPixel(kind,y,0),terrainPixel(kind,y,384));}for(let y=0;y<384;y+=11)assert.ok(Math.abs(terrainNoise(.001,y,64,11,6)-terrainNoise(383.999,y,64,11,6))<1e-7);});
